export enum DATE_RANGE {
  PAST_HOUR = 'h',
  PAST_24_HOURS = 'd',
  PAST_WEEK = 'w',
  PAST_MONTH = 'm',
  PAST_YEAR = 'y',
}

export const DEFAULT_QUERY_DESCRIPTION =
  'Search query. Use concise keywords, not full sentences.';

export const DEFAULT_COUNTRY_DESCRIPTION =
  '2-letter country code (e.g. "us", "ca", "de").';

export const querySchema = {
  type: 'string',
  description: DEFAULT_QUERY_DESCRIPTION,
} as const;

export const dateSchema = {
  type: 'string',
  enum: Object.values(DATE_RANGE),
  description: 'Date range for search results.',
} as const;

export const countrySchema = {
  type: 'string',
  description: DEFAULT_COUNTRY_DESCRIPTION,
} as const;

export const imagesSchema = {
  type: 'boolean',
  description: 'Whether to also run an image search.',
} as const;

export const videosSchema = {
  type: 'boolean',
  description: 'Whether to also run a video search.',
} as const;

export const newsSchema = {
  type: 'boolean',
  description: 'Whether to also run a news search.',
} as const;

/** Combined web search tool schema with all properties */
export const WebSearchToolSchema = {
  type: 'object',
  properties: {
    query: querySchema,
    date: dateSchema,
    country: countrySchema,
    images: imagesSchema,
    videos: videosSchema,
    news: newsSchema,
  },
  required: ['query'],
} as const;

export const WebSearchToolName = 'web_search';

export const WebSearchToolDescription = `Real-time web search. Returns numbered [N] sources. Max 3 per reply (counter shown).
TIPS: Concise keywords. date="d"/"w" for recency. news=true for breaking news. country for locale.`;

export const WebSearchToolDefinition = {
  name: WebSearchToolName,
  description: WebSearchToolDescription,
  schema: WebSearchToolSchema,
} as const;
